-- LOB viewer samples: one row per format the query view can render, for
-- checking previews by hand. Identical on both sides; nothing else depends on it.
-- The HTML and SVG rows embed scripts on purpose, to check the preview sandbox.

CREATE TABLE LOB_SAMPLES (
    SAMPLE_ID NUMBER(4)    NOT NULL,
    FORMAT    VARCHAR2(20) NOT NULL,
    BODY      CLOB,
    PAYLOAD   BLOB,
    CONSTRAINT PK_LOB_SAMPLES PRIMARY KEY (SAMPLE_ID)
);

-- SQL RAW literals max out at 2,000 bytes, so payloads are appended in hex chunks.
DECLARE
    PROCEDURE add_sample(p_id NUMBER, p_format VARCHAR2, p_body CLOB, p_hex SYS.ODCIVARCHAR2LIST) IS
        payload BLOB;
    BEGIN
        DBMS_LOB.CREATETEMPORARY(payload, TRUE);
        FOR i IN 1 .. p_hex.COUNT LOOP
            DBMS_LOB.WRITEAPPEND(payload, LENGTH(p_hex(i)) / 2, HEXTORAW(p_hex(i)));
        END LOOP;
        INSERT INTO LOB_SAMPLES (SAMPLE_ID, FORMAT, BODY, PAYLOAD) VALUES (p_id, p_format, p_body, payload);
        DBMS_LOB.FREETEMPORARY(payload);
    END;
BEGIN
    add_sample(1, 'png', NULL, SYS.ODCIVARCHAR2LIST(
        ''));
    add_sample(2, 'svg', '<svg xmlns="http://www.w3.org/2000/svg" width="200" height="120"><rect width="200" height="120" rx="12" fill="#255f85"/><circle cx="60" cy="60" r="36" fill="#b54f2e"/><text x="110" y="68" fill="#fff" font-family="sans-serif" font-size="20">SVG</text><script>alert(1)</script></svg>', SYS.ODCIVARCHAR2LIST(
        ''));
    add_sample(3, 'pdf', NULL, SYS.ODCIVARCHAR2LIST(
        ''));
    add_sample(4, 'docx', NULL, SYS.ODCIVARCHAR2LIST(
        ''));
    add_sample(5, 'html', '<!DOCTYPE html><html><body style="font-family:sans-serif"><h1>HTML sample</h1><p>Rendered <b>safely</b>: the script below must not run and the remote image must not load.</p><script>document.body.innerHTML="SCRIPT RAN"</script><img src="https://example.com/track.png" alt="remote image (blocked)"></body></html>', SYS.ODCIVARCHAR2LIST(
        ''));
    add_sample(6, 'json', '{"order":{"id":42,"items":[{"sku":"A-1","qty":2},{"sku":"B-7","qty":1}],"paid":true}}', SYS.ODCIVARCHAR2LIST(
        '7B226F72646572223A7B226964223A34322C226974656D73223A5B7B22736B75223A22412D31222C22717479223A327D2C7B22736B75223A22422D37222C22717479223A317D5D2C2270616964223A747275657D7D'));
    add_sample(7, 'xml', '<?xml version="1.0"?><invoice id="7"><line sku="A-1" qty="2">Widget</line><line sku="B-7" qty="1">Gadget</line><!-- note --></invoice>', SYS.ODCIVARCHAR2LIST(
        '3C3F786D6C2076657273696F6E3D22312E30223F3E3C696E766F6963652069643D2237223E3C6C696E6520736B753D22412D3122207174793D2232223E5769646765743C2F6C696E653E3C6C696E6520736B753D22422D3722207174793D2231223E4761646765743C2F6C696E653E3C212D2D206E6F7465202D2D3E3C2F696E766F6963653E'));
    add_sample(8, 'text', 'Plain text sample.
Second line with multi-byte characters: 5 € — ✓
	Indented third line.', SYS.ODCIVARCHAR2LIST(
        '506C61696E20746578742073616D706C652E0A5365636F6E64206C696E652077697468206D756C74692D6279746520636861726163746572733A203520E282AC20E2809420E29C930A09496E64656E746564207468697264206C696E652E'));
    add_sample(9, 'binary', NULL, SYS.ODCIVARCHAR2LIST(
        '',
        '',
        'DB251AE3C0A5D96D5F716AA13879DAFF014FF4A5EC03DDBAA38E3573480866B8D77491B2C77B7F375D22D17EDD1EFED1842B318F84A5682F03FBE329101FD2874582ECFFB49D1EBB16BCDD99FF95329829454D1B13AB63BB334B835B537EDD10'));
END;
/

COMMIT;
